create table if not exists public.support_requests (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject text not null, message text not null, category text not null default 'general', status text not null default 'open', priority text not null default 'normal', admin_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists support_requests_user_idx on public.support_requests(user_id,created_at desc); create table if not exists public.progression_actions (id uuid primary key default gen_random_uuid(), code text unique not null, label text not null, points integer not null default 0, enabled boolean not null default true, created_at timestamptz not null default now()); insert into public.progression_actions(code,label,points) values ('check_in','Check in',10),('verification','Verify a location',15),('review','Write a review',20),('favorite','Favorite a location',3),('location_diversity','Visit a new location',15),('qr_scan','Scan a QR experience',10),('route_complete','Complete a route',25),('social_post','Make a community post',10),('social_like','Like community content',2),('social_follow','Follow a community member',3),('contest_entry','Enter a contest',10),('contest_win','Win a contest',100),('event_rsvp','RSVP to an event',5),('event_attend','Attend an event',20) on conflict(code) do nothing; create unique index if not exists point_transactions_idempotency_idx on public.point_transactions(user_id,reason,reference_id) where reference_id is not null; create or replace function public.record_progression_action(p_action text,p_reference_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); pts integer; label_text text; today date:=current_date; last_date date; cur integer; longest integer; txn_id uuid; begin if uid is null then raise exception 'Not authenticated'; end if; select points,label into pts,label_text from public.progression_actions where code=p_action and enabled=true; if pts is null then raise exception 'Unknown progression action: %',p_action; end if; if p_reference_id is not null and exists(select 1 from public.point_transactions where user_id=uid and reason=p_action and reference_id=p_reference_id) then return jsonb_build_object('awarded',false,'reason','already_awarded'); end if; insert into public.point_transactions(user_id,points,reason,reference_id) values(uid,pts,p_action,p_reference_id) returning id into txn_id; select coalesce(current_streak,0),coalesce(longest_streak,0),last_activity_date into cur,longest,last_date from public.user_streaks where user_id=uid for update; if not found then cur:=1; longest:=1; insert into public.user_streaks(user_id,current_streak,longest_streak,last_activity_date,streak_started_at) values(uid,1,1,today,now()); elsif last_date=today then null; elsif last_date=today-1 then cur:=cur+1; longest:=greatest(longest,cur); update public.user_streaks set current_streak=cur,longest_streak=longest,last_activity_date=today,updated_at=now() where user_id=uid; else cur:=1; update public.user_streaks set current_streak=1,last_activity_date=today,streak_started_at=now(),updated_at=now() where user_id=uid; end if; update public.profiles set points=coalesce(points,0)+pts, level=floor((coalesce(points,0)+pts)/100)+1, streak=cur where id=uid; return jsonb_build_object('awarded',true,'action',p_action,'points',pts,'total_points',(select points from public.profiles where id=uid),'level',(select level from public.profiles where id=uid),'streak',cur,'transaction_id',txn_id); end; $$; create or replace function public.get_progression_summary() returns jsonb language sql security definer set search_path=public as $$ select jsonb_build_object('profile',(select to_jsonb(p) from public.profiles p where p.id=auth.uid()),'streak',(select to_jsonb(s) from public.user_streaks s where s.user_id=auth.uid()),'badges',(select coalesce(jsonb_agg(to_jsonb(x) order by x.earned_at desc),'[]'::jsonb) from (select ub.earned_at,b.* from public.user_badges ub join public.badges b on b.id=ub.badge_id where ub.user_id=auth.uid()) x),'user_leaderboard',(select coalesce(jsonb_agg(to_jsonb(x) order by x.rank),'[]'::jsonb) from (select * from public.community_leaderboard order by rank limit 25) x)); $$;
